const navFiles = ["regimen-artistas.html", "servicios.html", "nosotros.html", "recursos.html", "contacto.html"];

function prefix(lang) { return lang === "es" ? "" : "../"; }
function routePath(file) {
  const [path, fragment] = file.split("#");
  const route = path === "index.html" ? "" : path.replace(/\.html$/, "");
  return fragment ? `${route}#${fragment}` : route;
}
function publicPath(lang, file) { return lang === "es" ? `/${routePath(file)}` : `/${lang}/${routePath(file)}`; }
function diskPath(lang, file) { return lang === "es" ? join(root, file) : join(root, lang, file); }
function href(_lang, file) { return file === "index.html" ? "./" : routePath(file); }

function logo() {
  return `<span class="logo-variant foco foco-a" aria-hidden="true"><svg viewBox="0 0 44 44"><path d="M7 37 22 7l15 30"/><path class="accent" d="M14.5 26h15"/></svg><span class="logo-type"><b>ARTIVA</b><small>LABORAL</small></span></span>`;
}

function langLinks(lang, file) {
  return `<nav class="language-switcher" aria-label="Language / Idioma">
    ${langs.map(code => `<a href="${publicPath(code, file)}" lang="${code}" hreflang="${code}"${code === lang ? ' aria-current="true"' : ""}>${code === "ca" ? "CAT" : code.toUpperCase()}</a>`).join("")}
  </nav>`;
}

function header(lang, active, file) {
  const c = copy[lang];
  const links = navFiles.map((f, i) => `<a href="${href(lang, f)}"${active === f ? ' aria-current="page"' : ""}>${c.nav[i]}</a>`).join("");
  return `<header class="web-header">
    <a class="brand selected-logo" href="${href(lang, "index.html")}" aria-label="Artiva Laboral, ${c.footer[0].toLowerCase()}">${logo()}</a>
    <nav class="desktop-nav" aria-label="${c.navLabel}">${links}</nav>
    ${langLinks(lang, file)}
    <a class="web-header-cta" href="${href(lang, "contacto.html")}">${c.cta}</a>
    <button class="menu-toggle" type="button" aria-expanded="false" aria-controls="mobile-menu"><span>${c.menu}</span><i aria-hidden="true"></i></button>
    <nav class="mobile-menu" id="mobile-menu" aria-label="${c.navLabel}">${links}<a class="mobile-menu-cta" href="${href(lang, "contacto.html")}">${c.cta}</a></nav>
  </header>`;
}

function footer(lang) {
  const c = copy[lang];
  return `<footer class="web-footer">
    <div class="footer-brand">${logo()}<p>${lang === "ca" ? "Gestió laboral amb pols cultural." : lang === "en" ? "Employment management with a cultural pulse." : "Gestión laboral con pulso cultural."}</p></div>
    <div class="footer-links">
      <div>${["index.html", ...navFiles].map((f, i) => `<a href="${href(lang, f)}">${c.footer[i]}</a>`).join("")}</div>
      <div>${["privacidad.html", "cookies.html"].map((f, i) => `<a href="${href(lang, f)}">${c.legal[i + 1]}</a>`).join("")}<span>© <span data-year></span> Artiva Laboral</span></div>
    </div>
  </footer>`;
}

function cookieNotice(lang) {
  const c = copy[lang];
  return `<aside class="cookie-notice" data-cookie-notice role="dialog" aria-label="Cookies" hidden><p>${c.cookie} <a href="${href(lang, "cookies.html")}">${c.cookieMore}</a></p><button type="button" data-cookie-accept>${c.cookieOk}</button></aside>`;
}

function layout(lang, file, title, description, active, body, bodyClass = "inner-page") {
  const css = prefix(lang);
  const canonical = `${domain}${publicPath(lang, file)}`;
  const alternates = langs.map(code => `<link rel="alternate" hreflang="${code}" href="${domain}${publicPath(code, file)}">`).join("\n  ");
  const robots = file === "gracias.html" ? '  <meta name="robots" content="noindex, follow">\n' : "";
  return `<!doctype html>
<html lang="${lang}">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
${robots}  <title>${title}</title>
  <meta name="description" content="${description}">
  <link rel="canonical" href="${canonical}">
  ${alternates}
  <link rel="alternate" hreflang="x-default" href="${domain}${publicPath("es", file)}">
  <meta property="og:type" content="website">
  <meta property="og:locale" content="${copy[lang].locale}">
  <meta property="og:title" content="${title}">
  <meta property="og:description" content="${description}">
  <meta property="og:url" content="${canonical}">
  <meta name="theme-color" content="#07090c">
  <link rel="stylesheet" href="${css}styles.css">
  <link rel="stylesheet" href="${css}web.css">
</head>
<body class="web-home ${bodyClass}">
  <a class="skip-link" href="#contenido">${lang === "ca" ? "Salta al contingut" : lang === "en" ? "Skip to content" : "Saltar al contenido"}</a>
  ${header(lang, active, file)}
  <main id="contenido">${body}</main>
  ${footer(lang)}
  ${cookieNotice(lang)}
  <script src="${css}site.js"></script>
</body>
</html>`;
}

