function legalPage(lang, kind, file) {
  const t = legalContent[lang][kind];
  const pending = lang === "en" ? "Pending before public launch: legal owner, tax number and professional address." : lang === "ca" ? "Pendent abans de la publicació pública: titular legal, NIF i domicili professional." : "Pendiente antes de la publicación pública: titular legal, NIF y domicilio profesional.";
  const privacyOwner = lang === "en" ? "The data controller is Artiva Laboral. Privacy contact: info@artivalaboral.com." : lang === "ca" ? "El responsable del tractament és Artiva Laboral. Contacte de privacitat: info@artivalaboral.com." : "El responsable del tratamiento es Artiva Laboral. Contacto para privacidad: info@artivalaboral.com.";
  const sections = kind === "privacy" ? [[t.sections[0][0], privacyOwner], ...t.sections.slice(1)] : t.sections;
  return layout(lang, file, t.title, t.intro, "", `
    <section class="legal-hero"><p class="eyebrow">ARTIVA LABORAL · ${lang === "en" ? "Legal information" : lang === "ca" ? "Informació legal" : "Información legal"}</p><h1>${t.h1}</h1><p>${t.intro}</p></section>
    <article class="legal-document">${kind === "notice" ? `<div class="legal-pending"><strong>${pending}</strong></div>` : ""}${sections.map((x, i) => `<section><span>${String(i + 1).padStart(2, "0")}</span><div><h2>${x[0]}</h2><p>${x[1]}</p>${kind === "privacy" && i === 3 ? `<p><a href="https://formsubmit.co/privacy.pdf" target="_blank" rel="noopener">FormSubmit · ${lang === "en" ? "privacy information" : lang === "ca" ? "informació de privacitat" : "información de privacidad"} ↗</a></p>` : ""}${kind === "privacy" && i === 5 ? `<p><a href="https://www.aepd.es/" target="_blank" rel="noopener">Agencia Española de Protección de Datos ↗</a></p>` : ""}</div></section>`).join("")}<p class="legal-updated">${lang === "en" ? "Last updated" : lang === "ca" ? "Darrera actualització" : "Última actualización"}: 9.09.2026</p></article>
  `, "inner-page legal-page");
}

function thanks(lang) {
  const t = lang === "en" ? ["Thank you", "We have received your enquiry.", "The Artiva Laboral team will review it and contact you as soon as possible.", "Back to home"] : lang === "ca" ? ["Gràcies", "Hem rebut la teva consulta.", "L’equip d’Artiva Laboral la revisarà i es posarà en contacte amb tu tan aviat com sigui possible.", "Tornar a l’inici"] : ["Gracias", "Hemos recibido tu consulta.", "El equipo de Artiva Laboral la revisará y se pondrá en contacto contigo lo antes posible.", "Volver al inicio"];
  return layout(lang, "gracias.html", `${t[0]} — Artiva Laboral`, t[1], "", `<section class="thank-you"><p class="eyebrow">ARTIVA LABORAL</p><h1>${t[1]}</h1><p>${t[2]}</p><a class="button button-arrow" href="${href(lang, "index.html")}">${t[3]}</a></section>`, "inner-page thank-you-page");
}

